namespace mem {
	inline HANDLE DiverHandle;
	inline INT32 process_id;

	inline bool find_driver() {
		DiverHandle = CreateFileW(GENERATED_DEVICE_NAME_LINK,
			GENERIC_READ | GENERIC_WRITE,
			FILE_SHARE_READ | FILE_SHARE_WRITE,
			NULL,
			OPEN_EXISTING,
			0,
			NULL);

		if (DiverHandle == INVALID_HANDLE_VALUE) {
			return false;
		}

		return true;
	}

	inline void read_physical(PVOID address, PVOID buffer, DWORD size) {
		_RW arguments = { 0 };

		arguments.security = CODE_SECURITY;
		arguments.address = (ULONGLONG)address;
		arguments.buffer = (ULONGLONG)buffer;
		arguments.size = size;
		arguments.process_id = process_id;
		arguments.write = FALSE;
		arguments.passed_cr3 = cr3;

		DeviceIoControl(DiverHandle, CODE_RW, &arguments, sizeof(arguments), nullptr, NULL, NULL, NULL);
	}

	inline void read_buffer(uintptr_t address, void* buffer, size_t size) {
		if (!buffer || size == 0)
			return;
		read_physical((PVOID)address, buffer, static_cast<DWORD>(size));
	}

	inline void write_physical(PVOID address, PVOID buffer, DWORD size) {
		_RW arguments = { 0 };

		arguments.security = CODE_SECURITY;
		arguments.address = (ULONGLONG)address;
		arguments.buffer = (ULONGLONG)buffer;
		arguments.size = size;
		arguments.process_id = process_id;
		arguments.write = TRUE;
		arguments.passed_cr3 = cr3;

		DeviceIoControl(DiverHandle, CODE_RW, &arguments, sizeof(arguments), nullptr, NULL, NULL, NULL);
	}

	inline uintptr_t fetch_cr3() {
		uintptr_t cr3 = NULL;
		_MEMORY_OPERATION_DATA arguments = { 0 };

		arguments.pid = process_id;
		arguments.cr3 = (ULONGLONG*)&cr3;

		DeviceIoControl(DiverHandle, CODE_GET_DIR_BASE, &arguments, sizeof(arguments), nullptr, NULL, NULL, NULL);

		return cr3;
	}

	inline uintptr_t find_image() {
		uintptr_t image_address = { NULL };
		_BA arguments = { NULL };

		arguments.security = CODE_SECURITY;
		arguments.process_id = process_id;
		arguments.address = (ULONGLONG*)&image_address;

		DeviceIoControl(DiverHandle, CODE_BA, &arguments, sizeof(arguments), nullptr, NULL, NULL, NULL);

		return image_address;
	}

	inline INT32 find_process(LPCTSTR process_name) {
		PROCESSENTRY32 pt;
		HANDLE hsnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
		pt.dwSize = sizeof(PROCESSENTRY32);
		if (Process32First(hsnap, &pt)) {
			do {
				if (!lstrcmpi(pt.szExeFile, process_name)) {
					CloseHandle(hsnap);
					process_id = pt.th32ProcessID;
					return pt.th32ProcessID;
				}
			} while (Process32Next(hsnap, &pt));
		}
		CloseHandle(hsnap);

		return { NULL };
	}

	inline void close_driver() {
		if (DiverHandle != INVALID_HANDLE_VALUE) {
			CloseHandle(DiverHandle);
			DiverHandle = INVALID_HANDLE_VALUE;
		}
	}
}

inline bool Valid(const uint64_t adress)
{
	if (adress <= 0x400000 || adress == 0xCCCCCCCCCCCCCCCC || reinterpret_cast<void*>(adress) == nullptr || adress >
		0x7FFFFFFFFFFFFFFF) {
		return false;
	}
	return true;
}

template <typename T>
T read(uint64_t address) {
	T buffer{ };
	mem::read_physical((PVOID)address, &buffer, sizeof(T));
	return buffer;
}

inline bool read2(uint64_t address, void* buffer, size_t size) {
	mem::read_physical((PVOID)address, buffer, size);
	return true;
}

template<typename Type>
Type ReadChain(const std::uint64_t& Address, std::vector<std::uint64_t> Offsets)
{
	if (!Valid(Address) || !Address)
		return 0;

	std::uint64_t Value = Address;

	for (int i = 0; i < Offsets.size() - 1; i++)
	{
		const std::uint64_t& Offset = Offsets[i];
		Value = read<std::uint64_t>(Value + Offset);
	}

	return read<Type>(Value + Offsets[Offsets.size() - 1]);
}

inline std::string ReadWString(const std::uint64_t& Address)
{
	if (!Valid(Address) || !Address)
		return "";

	std::uint64_t NewAddress = read<std::uint64_t>(Address);
	if (!NewAddress)
		return "";

	int Length = read<int>(NewAddress + 0x10);
	if (Length <= 0)
		return "";

	std::vector<wchar_t> Buffer(Length + 1, L'\0');
	mem::read_physical(reinterpret_cast<PVOID>(NewAddress + 0x14), Buffer.data(), Length * sizeof(wchar_t));

	std::wstring TempString(Buffer.data(), Length);
	for (auto& ch : TempString) {
		if (ch < 32 || ch > 126) {
			ch = L'?';
		}
	}
	return std::string(TempString.begin(), TempString.end());
}

inline std::string read_wstr(uintptr_t address)
{
	if (!Valid(address) || !address)
		return "";

	wchar_t buffer[1024];
	mem::read_physical(reinterpret_cast<PVOID>(address), buffer, sizeof(buffer));
	buffer[1023] = L'\0';

	std::wstring wstr(buffer);
	for (auto& ch : wstr) {
		if (ch < 32 || ch > 126) {
			ch = L'?';
		}
	}
	return std::string(wstr.begin(), wstr.end());
}

inline std::string readstring(uint64_t Address)
{
	if (!Valid(Address) || !Address)
		return "";
	std::unique_ptr<char[]> buffer(new char[64]);
	mem::read_physical((PVOID)Address, buffer.get(), 64);
	return buffer.get();
}

template <typename T>
T write(uint64_t address, T buffer) {
	if (!Valid(address) || !address)
		return buffer;
	mem::write_physical((PVOID)address, &buffer, sizeof(T));
	return buffer;
}

template <typename T>
T ReadMemory(uint64_t address) {
	T buffer{ };
	if (!Valid(address) || !address)
		return buffer;
	mem::read_physical((PVOID)address, &buffer, sizeof(T));
	return buffer;
}

template<typename T>
bool read_struct(uint64_t address, T& out_struct) {
	if (!address) return false;
	mem::read_physical(reinterpret_cast<PVOID>(address), &out_struct, sizeof(T));
	return true;
}
